        @{ Arguments = @('-w', '55', 't3', 't4'); Output = @('  First line of a crown paragraph that is long enough', '  to need wrapping when formatted.', 'Second line has a different indentation and continues', 'the paragraph with more words here.  More text on', 'the third line.', 'Tagged:  the first line of a tagged paragraph that', 'goes on and on for a while', '    and the second line is indented differently than', '    the first one was before.', 'Short'); Errors = @(); ExitCode = 0 }
        @{ Arguments = @('-u', '-w', '55', 't6'); Output = @('Mr. Smith went to Washington. He said "hello."', 'Then left.  End.'); Errors = @(); ExitCode = 0 }
