        @{ Arguments = @('-w', '65', 't1'); Output = @('The quick brown fox jumps over the lazy dog. This sentence', 'is here to make the paragraph longer than one line, so that', 'fmt has to break it. Another sentence follows!  And one more', '(with parentheses) to test the bonus rules, commas, semicolons;', 'and colons: all of them.', '', '  Indented paragraph with several short lines that should be', '  joined together into a single nicely filled block of text.', '', '	Tabbed paragraph	with tabs inside and a really', '	long word Pneumonoultramicroscopicsilicovolcanoconiosis', '	in it.'); Errors = @(); ExitCode = 0 }
        @{ Arguments = @('-w', '65', 't3', 't4'); Output = @('  First line of a crown paragraph that is long enough to need', '  wrapping when formatted.', 'Second line has a different indentation and continues the', 'paragraph with more words here.  More text on the third line.', 'Tagged:  the first line of a tagged paragraph that goes on', 'and on for a while', '    and the second line is indented differently than the first', '    one was before.', 'Short'); Errors = @(); ExitCode = 0 }
        @{ Arguments = @('-u', '-w', '65', 't6'); Output = @('Mr. Smith went to Washington. He said "hello."  Then left.  End.'); Errors = @(); ExitCode = 0 }
