    ) {
        $r = Invoke-TestGnu fmt $Arguments -WorkingDirectory $dir
        $r.Output | Should -Be $Output
        @($r.Errors | ForEach-Object { ($_ -split "`n")[0] }) | Should -Be $Errors
        $r.ExitCode | Should -Be $ExitCode
    }

    It 'checks widths and reads the pipeline' {
        (Invoke-TestGnu fmt '-g', '80').ErrorText | Should -Be "fmt: invalid width: '80': Numerical result out of range"
        (Invoke-TestGnu fmt '-w', '2501').ErrorText | Should -Be "fmt: invalid width: '2501': Numerical result out of range"
        (Invoke-TestGnu fmt '--width=x').ErrorText | Should -Be "fmt: invalid width: 'x'"
        (Invoke-TestGnu fmt '--goal=y').ErrorText | Should -Be "fmt: invalid width: 'y'"
        (Invoke-TestGnu fmt '-w', '50', '-g', '60').ErrorText | Should -Be "fmt: invalid width: '60': Numerical result out of range"
        (Invoke-TestGnu fmt '-w', '0' -InputObject 'a b').Output | Should -Be @('a', 'b')
        (Invoke-TestGnu fmt '--crown-margin', '--uniform-spacing' -InputObject 'a  b', '  c').Output | Should -Be @('a b c')
        (Invoke-TestGnu fmt '--split-only', '--width=5' -InputObject 'aa bb cc').Output | Should -Be @('aa', 'bb', 'cc')
        (Invoke-TestGnu fmt '--tagged-paragraph', '--prefix=> ' -InputObject '> x', '> y').Output | Should -Be @('> x', '> y')
        (Invoke-TestGnu fmt 'nosuch' -WorkingDirectory $dir).ExitCode | Should -Be 1
        $null = New-TestFile -Path (Join-Path $dir 'prefix-eof') -Content "a`n#"
        (Invoke-TestGnu fmt '-p', '#', 'prefix-eof' -WorkingDirectory $dir).Output | Should -Be @('a', '#')
        (Invoke-TestGnu fmt '-c' -InputObject 'one line').Output | Should -Be @('one line')
        (Invoke-TestGnu fmt '-t', '-w', '10' -InputObject 'aaa bbb ccc ddd').Output | Should -Be @('aaa bbb', '   ccc', '   ddd')
        (Invoke-TestGnu fmt '-t', '-w', '10' -InputObject '  aaa bbb ccc ddd').Output | Should -Be @('  aaa bbb', 'ccc ddd')
        (Invoke-TestGnu fmt '-t', '-w', '10' -InputObject 'aaa', '  bbb', '', '  ccc ddd eee fff').Output | Should -Be @('aaa bbb', '', '  ccc ddd', 'eee fff')
    }
}
